<script>(()=>{const form=document.getElementById('bike-create-form');if(!form)return;const customers=@json($customers->map(fn($customer)=>['id'=>$customer->id,'label'=>($customer->name ?: 'Walk-in').' — '.$customer->phone])->values());const search=form.querySelector('[data-customer-search]');const customerId=form.querySelector('[data-customer-id]');const selectCustomer=()=>{const match=customers.find(customer=>customer.label.toLowerCase()===search.value.trim().toLowerCase());customerId.value=match?.id||'';search.setCustomValidity(search.value&& !match?'Choose a customer from the search results.':'');};search.addEventListener('input',selectCustomer);const sync=()=>{const mode=form.querySelector('[name=customer_mode]:checked').value;form.querySelector('[data-existing-customer]').classList.toggle('hidden',mode!=='existing');form.querySelector('[data-new-customer]').classList.toggle('hidden',mode!=='new');search.required=mode==='existing';if(mode!=='existing')search.setCustomValidity('');};form.querySelectorAll('[name=customer_mode]').forEach(x=>x.addEventListener('change',sync));form.addEventListener('submit',()=>{if(form.querySelector('[name=customer_mode]:checked').value==='existing')selectCustomer();});const toggle=form.querySelector('[data-technician-toggle]');toggle.addEventListener('change',()=>form.querySelector('[data-technician-fields]').classList.toggle('hidden',!toggle.checked));sync();})();</script></div></x-layouts::app>
